'use client';
import { useEffect, useState } from 'react';
import { initializeRoutes } from './src/components/index';

export default function RouteInitializer({ 
  children 
}: { 
  children: React.ReactNode 
}) {
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    // Вызываем инициализацию только на клиенте
    initializeRoutes()
      .then(() => setIsReady(true))
      .catch((error) => {
        console.error('Failed to initialize routes:', error);
        setIsReady(true); // Показываем UI даже при ошибке
      });
  }, []);

  // Можно показать loader пока инициализируется
  if (!isReady) {
    return <div>Загрузка приложения...</div>;
  }

  return <>{children}</>;
}